package com.nextrade.persistence.entity; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*;
@Entity @Table(name="orders",indexes={@Index(name="ix_orders_instrument_status",columnList="instrumentId,status"),@Index(name="ix_orders_client",columnList="userId,clientOrderId"),@Index(name="ix_orders_book",columnList="instrumentId,side,status,limitPrice,sequence")}) public class OrderEntity { @Id private UUID id; @Column(nullable=false) private UUID userId; @Column(nullable=false) private UUID instrumentId; @Column(nullable=false,length=10) private String side; @Column(nullable=false,length=20) private String type; @Column(nullable=false,length=20) private String status; @Column(nullable=false,length=10) private String tif; @Column(nullable=false,precision=19,scale=4) private BigDecimal quantity; @Column(nullable=false,precision=19,scale=4) private BigDecimal filledQuantity; @Column(precision=19,scale=4) private BigDecimal limitPrice; @Column(precision=19,scale=4) private BigDecimal stopPrice; @Column(precision=19,scale=4) private BigDecimal avgFillPrice; @Column(length=128) private String clientOrderId; private Instant expiresAt; private Instant triggeredAt; @Column(nullable=false) private long sequence; @Version private long version; public OrderEntity(){} public UUID getId(){return id;} public void setId(UUID v){id=v;} public UUID getUserId(){return userId;} public void setUserId(UUID v){userId=v;} public UUID getInstrumentId(){return instrumentId;} public void setInstrumentId(UUID v){instrumentId=v;} public String getSide(){return side;} public void setSide(String v){side=v;} public String getType(){return type;} public void setType(String v){type=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getTif(){return tif;} public void setTif(String v){tif=v;} public BigDecimal getQuantity(){return quantity;} public void setQuantity(BigDecimal v){quantity=v;} public BigDecimal getFilledQuantity(){return filledQuantity;} public void setFilledQuantity(BigDecimal v){filledQuantity=v;} public BigDecimal getLimitPrice(){return limitPrice;} public void setLimitPrice(BigDecimal v){limitPrice=v;} public BigDecimal getStopPrice(){return stopPrice;} public void setStopPrice(BigDecimal v){stopPrice=v;} public BigDecimal getAvgFillPrice(){return avgFillPrice;} public void setAvgFillPrice(BigDecimal v){avgFillPrice=v;} public String getClientOrderId(){return clientOrderId;} public void setClientOrderId(String v){clientOrderId=v;} public Instant getExpiresAt(){return expiresAt;} public void setExpiresAt(Instant v){expiresAt=v;} public Instant getTriggeredAt(){return triggeredAt;} public void setTriggeredAt(Instant v){triggeredAt=v;} public long getSequence(){return sequence;} public void setSequence(long v){sequence=v;} public long getVersion(){return version;} }
